namespace Demo;

public class Calculator
{
    /// <summary>Adds two integers.</summary>
    public int Add(int a, int b) => a + b;

    public double Add(double a, double b) => a + b;

    public int Use() => Add(1, 2);
}

namespace Demo;

public class Calculator
{
    /// <summary>Adds two integers.</summary>
    public int Add(int a, int b) => a + b;

    public double Add(double a, double b) => a + b;

    public int Use() => Add(1, 2);

    public int UseTwice() => Add(3, 4) + Add(5, 6);
}

namespace Demo;

public class Extra
{
    public int Go() => new Calculator().Add(7, 8) + System.Math.Abs(-1);
}
